cd /private/tmp/claude-501/-Users-saranatour-workspace-Personal-Website/49047826-6d5e-44a0-9039-26bec57cca86/scratchpad && cat > og.mjs <<'EOF'
import sharp from 'sharp';
const SRC = '../images/1.jpg';
const sizes = { discord: [1200, 630], twitter: [1200, 675], linkedin: [1200, 627] };
const socials = [['Discord', 'sarant'], ['Reddit', '_sarant'], ['Twitter', '_sarant'], ['GitHub', 'saranatour'], ['LinkedIn', 'saranatour']];
const C = { bg: '#f4f1df', navy: '#10141f', green: '#5fb85a', blue: '#6fa3ec', mint: '#bfe3cf' };

// halftone: dot radius grows toward the bottom-left and top-right corners
const dots = (w, h, step = 22) => {
  let s = '';
  for (let y = step / 2; y < h; y += step) for (let x = step / 2; x < w; x += step) {
    const d = Math.hypot(x / w - 0.5, y / h - 0.5) / 0.71; // 0 center → 1 corner
    const r = Math.max(0, (d - 0.35) * step * 0.75);
    if (r > 0.6) s += `<circle cx="${x}" cy="${y}" r="${r.toFixed(1)}" fill="${(x + y) % (step * 2) < step ? C.green : C.blue}" opacity=".85"/>`;
  }
  return s;
};

for (const [name, [w, h]] of Object.entries(sizes)) {
  const d = Math.round(h * 0.62), cx = Math.round(h * 0.2 + d / 2) + 40, cy = h / 2;
  const portrait = await sharp(SRC).resize(d, d)
    .composite([{ input: Buffer.from(`<svg width="${d}" height="${d}"><circle cx="${d/2}" cy="${d/2}" r="${d/2}"/></svg>`), blend: 'dest-in' }]).png().toBuffer();
  const tx = cx + d / 2 + 60;
  const rows = socials.map(([k, v], i) => {
    const y = cy - 20 + i * 44;
    return `<circle cx="${tx + 6}" cy="${y - 8}" r="6" fill="${C.green}"/>
      <text x="${tx + 28}" y="${y}" font-size="26" fill="${C.navy}" opacity=".6">${k}</text>
      <text x="${tx + 170}" y="${y}" font-size="26" font-weight="700" fill="${C.navy}">${v}</text>`;
  }).join('');
  const svg = `<svg width="${w}" height="${h}" xmlns="http://www.w3.org/2000/svg" font-family="Helvetica Neue, Helvetica, Arial, sans-serif">
    <rect width="${w}" height="${h}" fill="${C.bg}"/>${dots(w, h)}
    <circle cx="${cx}" cy="${cy}" r="${d / 2 + 14}" fill="${C.bg}"/>
    <circle cx="${cx}" cy="${cy}" r="${d / 2 + 14}" fill="none" stroke="${C.navy}" stroke-width="3" stroke-dasharray="1 12" stroke-linecap="round"/>
    <text x="${tx}" y="${cy - 80}" font-size="68" font-weight="800" fill="${C.navy}">Sara Natour</text>
    ${rows}</svg>`;
  await sharp(Buffer.from(svg)).composite([{ input: portrait, left: Math.round(cx - d / 2), top: Math.round(cy - d / 2) }])
    .png().toFile(`og-${name}.png`);
}
EOF
